"""Copy settings and History once, keeping the source application closed."""
from contextlib import closing
import hashlib
import json
import os
from pathlib import Path
import sqlite3
import time


def fingerprint(path):
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.digest()


def history_digest(db):
    digest = hashlib.sha256()
    for row in db.execute("SELECT * FROM results ORDER BY sequence"):
        digest.update(repr(row).encode("utf-8"))
        digest.update(b"\n")
    return digest.digest()


def copy_storage(source, destination):
    if not destination.is_dir() or any(destination.iterdir()):
        raise FileExistsError("Destination must be an empty folder")
    overrides = source / "config/local_overrides.json"
    state = source / "output/desktop-state.json"
    settings = json.loads(state.read_text(encoding="utf-8"))
    if not isinstance(settings, dict):
        raise ValueError("Invalid state")
    if not isinstance(json.loads(overrides.read_text(encoding="utf-8")), dict):
        raise ValueError("Invalid overrides")
    history_name = settings.get("history_path", "output/history.sqlite3")
    if not isinstance(history_name, str) or not history_name:
        raise ValueError("Invalid history path")
    history = Path(history_name)
    if not history.is_absolute():
        history = source / history
    originals = (overrides, state, history)
    before = {path: fingerprint(path) for path in originals}
    with closing(sqlite3.connect(history.resolve().as_uri() + "?mode=ro", uri=True)) as old:
        old.execute("BEGIN")
        if old.execute("PRAGMA integrity_check").fetchall() != [("ok",)]:
            raise ValueError("Source database integrity")
        expected = history_digest(old)
        (destination / "config").mkdir()
        (destination / "output").mkdir()
        for original, target in (
            (overrides, destination / "config/local_overrides.json"),
            (state, destination / "output/desktop-state.json"),
        ):
            with target.open("xb") as stream:
                stream.write(original.read_bytes())
            if fingerprint(target) != before[original]:
                raise ValueError("Settings verification")
        target_db = destination / "output/history.sqlite3"
        with target_db.open("xb"):
            pass
        deadline = time.monotonic() + 60
        def progress(status, remaining, total):
            if time.monotonic() > deadline:
                raise TimeoutError("Database copy timed out")
        with closing(sqlite3.connect(target_db)) as new:
            old.backup(new, pages=256, progress=progress)
            if new.execute("PRAGMA integrity_check").fetchall() != [("ok",)]:
                raise ValueError("Copied database integrity")
            if history_digest(new) != expected:
                raise ValueError("History contents verification")
            if new.execute("PRAGMA user_version").fetchone() != old.execute("PRAGMA user_version").fetchone():
                raise ValueError("History version verification")
    if any(fingerprint(path) != before[path] for path in originals):
        raise ValueError("Source changed during copy")


def main():
    try:
        profile = os.environ.get("LOCALAPPDATA", "")
        if not profile or not Path(profile).is_absolute():
            raise ValueError("User profile unavailable")
        copy_storage(Path(__file__).resolve().parent, Path(profile) / "AppHealthChecker")
        print("SETTINGS COPY: PASS")
        print("HISTORY COPY: PASS")
        print("SOURCE FILES: UNCHANGED")
    except Exception as exc:
        print("COPY STOPPED: " + type(exc).__name__)
        print("Do not retry or delete files; report this status first.")


if __name__ == "__main__":
    main()
